{"results": [{"id": "hp_doc_14819bc152f61099ab6b0c64982ab07b63e6f573bfb587ceaf3ef6f53018bc50", "title": "Oklahoma State Cowboys basketball", "text": "The Oklahoma State Cowboys basketball team represents Oklahoma State University in Stillwater, Oklahoma, United States in NCAA Division I men's basketball competition. (All women's teams at the school are known as Cowgirls.) The Cowboys currently compete in the Big 12 Conference.", "score": 40.3354}, {"id": "hp_doc_1b9d8c09d8405fd43ae68f33ac9ec38f5d755601d20df28e95001db336e657d7", "title": "2015–16 Oklahoma State Cowboys basketball team", "text": "The 2015–16 Oklahoma State Cowboys basketball team represented Oklahoma State University in the 2015–16 NCAA Division I men's basketball season. This was head coach Travis Ford's eighth and final season at Oklahoma State. The Cowboys were members of the Big 12 Conference and played their home games at Gallagher-Iba Arena. They finished the season 12–20, 3–15 in Big 12 play to finish in ninth place. They lost in the first round of the Big 12 Tournament to Kansas State.", "score": 35.7917}, {"id": "hp_doc_f28efc6d0cebd9249ab32b22573bf18206e1a15a062f18ce1b06f46bba40e7e7", "title": "Jawun Evans", "text": "Jawun Evans (born July 26, 1996) is an American basketball player for the Los Angeles Clippers of the National Basketball Association (NBA). A point guard, he played college basketball for Oklahoma State, Evans was named an All-American in the 2016–17 season.", "score": 17.5439}], "remaining_searches": 1}
